CREATE     PROCEDURE [synapse_ce].[usp_Insert_apuk_accreditedprogramme]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_accreditedprogramme]
	(
		[apuk_accreditationcontactid],
		[apuk_accreditationcontactid_entitytype],
		[apuk_accreditationcontactidname],
		[apuk_accreditationcontactidyominame],
		[apuk_accreditedprogrammeid],
		[apuk_amrduedate],
		[apuk_conditions],
		[apuk_deliverymethod],
		[apuk_departmentid],
		[apuk_departmentid_entitytype],
		[apuk_departmentidname],
		[apuk_displayonweb],
		[apuk_durationyears],
		[apuk_enddate],
		[apuk_endmonth],
		[apuk_endyear],
		[apuk_level],
		[apuk_name],
		[apuk_reaccreditationapplication],
		[apuk_staffnotes],
		[apuk_startdate],
		[apuk_startmonth],
		[apuk_startyear],
		[apuk_status],
		[apuk_universityid],
		[apuk_universityid_entitytype],
		[apuk_universityidname],
		[apuk_universityidyominame],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_accreditationcontactid],
		stg.[apuk_accreditationcontactid_entitytype],
		stg.[apuk_accreditationcontactidname],
		stg.[apuk_accreditationcontactidyominame],
		stg.[apuk_accreditedprogrammeid],
		stg.[apuk_amrduedate],
		stg.[apuk_conditions],
		stg.[apuk_deliverymethod],
		stg.[apuk_departmentid],
		stg.[apuk_departmentid_entitytype],
		stg.[apuk_departmentidname],
		stg.[apuk_displayonweb],
		stg.[apuk_durationyears],
		stg.[apuk_enddate],
		stg.[apuk_endmonth],
		stg.[apuk_endyear],
		stg.[apuk_level],
		stg.[apuk_name],
		stg.[apuk_reaccreditationapplication],
		stg.[apuk_staffnotes],
		stg.[apuk_startdate],
		stg.[apuk_startmonth],
		stg.[apuk_startyear],
		stg.[apuk_status],
		stg.[apuk_universityid],
		stg.[apuk_universityid_entitytype],
		stg.[apuk_universityidname],
		stg.[apuk_universityidyominame],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_accreditedprogramme] stg
		LEFT JOIN [synapse_ce].[apuk_accreditedprogramme] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
